contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address addr) public payable {
        require(addr == address(this));
        uint256 beforeBal = c.balances(addr); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterBal = c.balances(addr); if (__ESBMC_reverted()) return;
        assert((reverted && afterBal == beforeBal) || (!reverted && afterBal == 0));
    }
    receive() external payable {}
}

