pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address addr) internal {
        addr = address(this);
        uint256 beforeBal;
        try c.balances(addr) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.balances(addr) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue((reverted && afterBal == beforeBal) || (!reverted && afterBal == 0));
    }

    function testFuzz_run(address addr) public {
        _run(addr);
    }

    receive() external payable {}
}
